"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { ArrowRight, BarChart3, Bell, BookOpen, Bot, Boxes, Building2, Check, ChevronRight, CircleAlert,
  ClipboardCheck, Clock3, Eye, FileSearch, FlaskConical, Gauge, Lightbulb, LockKeyhole, Menu, MessageSquareText,
  Network, Play, Plus, Search, Send, ShieldCheck, Sparkles, Target, Users } from "lucide-react";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = Record<string, any>;
const offerings = [
  { name: "Financial Analysis Intelligence", code: "FAI", accent: "mint", text: "Context-aware financial assessment with traceable evidence." },
  { name: "Lending Intelligence", code: "LND", accent: "violet", text: "Governed decision support across the lending lifecycle." },
  { name: "Compliance Intelligence", code: "CMP", accent: "amber", text: "Explainable controls, policy checks and investigation support." },
];

async function api(url: string, options?: RequestInit): Promise<Json> {
  const response = await fetch(url, { ...options, headers: { "Content-Type": "application/json", ...(options?.headers ?? {}) } });
  const json = (await response.json()) as Json;
  if (!response.ok) throw new Error(json.error ?? "Request failed");
  return json;
}

export function PortalApp() {
  const path = usePathname();
  const isPublic = ["/", "/products", "/connect", "/hackathon/register", "/login", "/signin"].includes(path);
  return <div className="min-h-screen bg-[#f6f7f4] text-[#14231e]"><TopNav publicMode={isPublic} />{isPublic ? <PublicRouter path={path} /> : <WorkspaceRouter path={path} />}</div>;
}

function TopNav({ publicMode }: { publicMode: boolean }) {
  const [open, setOpen] = useState(false);
  return <header className="sticky top-0 z-50 border-b border-[#dfe5df] bg-[#f8faf7]/90 backdrop-blur-xl"><div className="mx-auto flex h-[72px] max-w-[1440px] items-center justify-between px-5 md:px-9">
    <Link href="/" className="flex items-center gap-3"><Logo /><div><div className="text-[17px] font-bold tracking-[-.03em]">azentio<span className="text-[#5d42e6]">.ai</span></div><div className="text-[9px] font-semibold uppercase tracking-[.2em] text-[#6c7b74]">Collective</div></div></Link>
    <nav className="hidden items-center gap-8 text-sm font-medium text-[#53625b] md:flex"><Link href="/products">Offerings</Link><Link href="/#how">How it works</Link><Link href="/learning">Collective learning</Link><Link href="/connect">Contact</Link></nav>
    <div className="hidden items-center gap-3 md:flex"><Link href="/login" className="btn-secondary">{publicMode ? "Sign in" : "Switch workspace"}</Link><Link href="/connect" className="btn-primary">Request a demo <ArrowRight size={15} /></Link></div>
    <button onClick={() => setOpen(!open)} className="md:hidden" aria-label="Open menu"><Menu /></button></div>{open && <div className="grid gap-4 border-t bg-white p-5 md:hidden"><Link href="/products">Offerings</Link><Link href="/learning">Collective learning</Link><Link href="/connect">Contact</Link><Link href="/login">Enter portal</Link></div>}</header>;
}
function Logo() { return <div className="grid h-10 w-10 place-items-center rounded-[13px] bg-[#15251f] text-white shadow-lg"><Network size={20} /></div>; }

function PublicRouter({ path }: { path: string }) {
  if (path === "/products") return <Products />;
  if (path === "/connect") return <PublicForm kind="demo" />;
  if (path === "/hackathon/register") return <PublicForm kind="hackathon" />;
  if (path === "/login") return <Login />;
  if (path === "/signin") return <SignIn />;
  return <><Landing /><PublicUpdates /></>;
}

function Landing() {
  return <main><section className="relative overflow-hidden px-5 pb-24 pt-20 md:px-9 md:pb-32 md:pt-28"><div className="hero-grid absolute inset-0 opacity-70" /><div className="relative mx-auto grid max-w-[1340px] items-center gap-16 lg:grid-cols-[1.05fr_.95fr]">
    <div><Pill icon={<Sparkles size={13} />}>Governed intelligence, shared safely</Pill><h1 className="mt-7 max-w-[770px] text-[clamp(3.4rem,7vw,7.4rem)] font-semibold leading-[.88] tracking-[-.07em]">Build intelligence.<br /><span className="text-[#5d42e6]">Create shared value.</span></h1><p className="mt-8 max-w-xl text-lg leading-8 text-[#596860]">A secure enterprise AI experience where client evidence becomes approved collective learning — and learning becomes product improvement.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/login" className="btn-primary btn-large">Explore the live workflow <ArrowRight size={17} /></Link><Link href="/products" className="btn-secondary btn-large">Discover offerings</Link></div><div className="mt-10 flex flex-wrap gap-6 text-xs font-semibold uppercase tracking-[.12em] text-[#66756e]"><span className="flex items-center gap-2"><ShieldCheck size={16} className="text-[#008d70]" /> Tenant isolated</span><span className="flex items-center gap-2"><Eye size={16} className="text-[#008d70]" /> Approved evidence only</span><span className="flex items-center gap-2"><LockKeyhole size={16} className="text-[#008d70]" /> Explicit consent</span></div></div><IntelligenceVisual />
  </div></section><section className="border-y border-[#dce4dd] bg-[#15251f] px-5 py-7 text-white"><div className="mx-auto grid max-w-[1340px] gap-5 text-center sm:grid-cols-4"><Stat n="3" t="tenant boundaries" /><Stat n="60s" t="withdrawal SLA" /><Stat n="100%" t="grounded evidence" /><Stat n="0" t="private rows exposed" /></div></section>
  <section id="how" className="px-5 py-24 md:px-9"><div className="mx-auto max-w-[1340px]"><SectionHead eyebrow="From observation to action" title="One governed learning loop." text="Private by default. Shared only with consent and review. Every insight remains connected to permitted evidence." /><div className="mt-14 grid gap-4 lg:grid-cols-4"><Step n="01" icon={<MessageSquareText />} title="Observe" text="Clients capture structured market evidence in a tenant-private workspace." /><Step n="02" icon={<ClipboardCheck />} title="Review" text="Moderators redact, de-identify and approve a separate shared copy." /><Step n="03" icon={<Bot />} title="Synthesize" text="AIRA answers only from approved publications with valid references." /><Step n="04" icon={<Target />} title="Improve" text="Product owners link themes to tracked ideas and close the feedback loop." /></div></div></section>
  <section className="px-5 pb-24 md:px-9"><div className="mx-auto grid max-w-[1340px] gap-6 rounded-[34px] bg-[#e7f3ee] p-7 md:grid-cols-[1fr_auto] md:p-12"><div><div className="kicker">Special challenge demo</div><h2 className="mt-3 text-4xl font-semibold tracking-[-.045em]">See trust become a product capability.</h2><p className="mt-3 text-[#5b6a63]">Test the complete seasonal SME scenario across client, moderator and product-owner workspaces.</p></div><Link href="/login" className="btn-primary self-center">Launch demo <Play size={16} /></Link></div></section></main>;
}

function IntelligenceVisual() { return <div className="relative mx-auto w-full max-w-[570px]"><div className="absolute -right-20 -top-24 h-64 w-64 rounded-full bg-[#b8f5dd] opacity-60 blur-3xl" /><div className="relative rounded-[30px] border border-white/80 bg-white/75 p-5 shadow-[0_30px_80px_rgba(30,54,43,.14)] backdrop-blur-xl"><div className="flex items-center justify-between border-b border-[#e2e8e3] pb-4"><div><div className="kicker">AIRA signal</div><div className="mt-1 font-semibold">Seasonality context</div></div><span className="status green"><Check size={12} /> 3 orgs</span></div><div className="my-5 rounded-2xl bg-[#172720] p-5 text-white"><div className="flex items-center gap-2 text-xs text-[#a9bdb3]"><Bot size={14} /> Grounded synthesis</div><p className="mt-3 text-lg leading-7">Seasonal SME cash flows may need like-for-like operating-cycle comparisons.</p><div className="mt-4 flex gap-2"><span className="source">PUB-001</span><span className="source">PUB-002</span><span className="source">PUB-003</span></div></div><div className="grid grid-cols-3 gap-3"><MiniCard icon={<LockKeyhole />} label="Private source" value="Isolated" /><MiniCard icon={<ShieldCheck />} label="Review" value="Approved" /><MiniCard icon={<Lightbulb />} label="Idea" value="Under review" /></div></div></div>; }

function Products() { return <main className="px-5 py-20 md:px-9"><div className="mx-auto max-w-[1340px]"><SectionHead eyebrow="Azentio intelligence suite" title="Purpose-built intelligence for financial institutions." text="Explore approved synthetic demonstrations. No sandbox output is an approved financial or business decision." /><div className="mt-14 grid gap-5 lg:grid-cols-3">{offerings.map((o, i) => <div key={o.code} className="product-card"><div className={`product-icon ${o.accent}`}><Boxes /></div><span className="text-xs font-bold tracking-[.16em] text-[#7a8780]">0{i + 1} / {o.code}</span><h2 className="mt-10 text-2xl font-semibold tracking-[-.035em]">{o.name}</h2><p className="mt-3 leading-7 text-[#66736d]">{o.text}</p><Link href="/login" className="mt-10 inline-flex items-center gap-2 text-sm font-bold">Open synthetic demo <ArrowRight size={15} /></Link></div>)}</div></div></main>; }

function PublicForm({ kind }: { kind: "demo" | "hackathon" }) {
  const [result, setResult] = useState<Json | null>(null), [error, setError] = useState("");
  async function submit(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); setError(""); const fd = new FormData(e.currentTarget); try { setResult(await api("/api/public-form", { method: "POST", body: JSON.stringify({ kind, ...Object.fromEntries(fd) }) })); } catch (x) { setError((x as Error).message); } }
  return <main className="px-5 py-16 md:px-9"><div className="mx-auto grid max-w-[1100px] gap-10 lg:grid-cols-[.8fr_1.2fr]"><div className="pt-6"><Pill icon={kind === "demo" ? <Gauge size={13} /> : <FlaskConical size={13} />}>{kind === "demo" ? "Product conversation" : "Hackathon interest"}</Pill><h1 className="mt-7 text-5xl font-semibold leading-[.98] tracking-[-.055em]">{kind === "demo" ? "Let’s build the next intelligence advantage." : "Build intelligence with us."}</h1><p className="mt-5 leading-7 text-[#66736d]">Your details are persisted securely. This demo records a reference but does not claim an email was delivered.</p></div><div className="surface p-7 md:p-9">{result ? <Success result={result} /> : <form onSubmit={submit} className="grid gap-5"><Field label="Full name" name="name" /><Field label="Work email" name="email" type="email" /><Field label="Company" name="company" /><Field label={kind === "demo" ? "What would you like to explore?" : "Team or challenge interest"} name="message" area />{error && <Alert text={error} />}<button className="btn-primary mt-2 justify-center" type="submit">Record interest <Send size={15} /></button></form>}</div></div></main>;
}

function Login() {
  const router = useRouter(), [busy, setBusy] = useState(""), [error, setError] = useState(""), [memberships, setMemberships] = useState<Json[] | null>(null);
  useEffect(() => { api("/api/session").then(r => setMemberships(r.memberships)).catch(x => { if (/Sign in is required/.test(x.message)) router.replace("/signin"); else { setError(x.message); setMemberships([]); } }); }, [router]);
  const icon = (kind: string) => kind === "client" ? <Building2 /> : kind === "moderator" ? <ClipboardCheck /> : kind === "product_owner" ? <Lightbulb /> : <FlaskConical />;
  const blurb: Record<string, string> = { client_admin: "Manage members, submit evidence and follow status.", client_member: "Submit evidence, follow status and browse approved learning.", moderator: "Review private sources and publish de-identified copies.", product_owner: "Turn approved themes into tracked product improvements.", employee: "Explore internal experiments and guided playgrounds." };
  async function choose(id: string) {
    setBusy(id); setError("");
    try { const r = await api("/api/session", { method: "POST", body: JSON.stringify({ membershipId: id }) }); router.push(r.home); } catch (x) { setError((x as Error).message); setBusy(""); }
  }
  return <main className="px-5 py-14 md:px-9"><div className="mx-auto max-w-[980px]"><div className="text-center"><Pill icon={<LockKeyhole size={13} />}>Membership-backed access</Pill><h1 className="mt-6 text-5xl font-semibold tracking-[-.055em]">Choose a governed workspace.</h1><p className="mx-auto mt-4 max-w-2xl text-[#66736d]">Only workspaces your account is a member of are listed. The server verifies the membership on every selection and derives your role and organisation from it.</p></div>
    {error && <div className="mx-auto mt-6 max-w-xl"><Alert text={error} /></div>}
    {memberships?.length === 0 && !error && <div className="mt-10"><Empty icon={<LockKeyhole />} title="No workspaces available" text="Ask your organisation administrator for an invitation." /></div>}
    <div className="mt-12 grid gap-4 md:grid-cols-2">{(memberships ?? []).map(m => <button key={m.id} onClick={() => choose(m.id)} className="persona-card text-left"><span className="persona-icon">{icon(m.kind)}</span><span className="min-w-0 flex-1"><span className="block font-bold">{m.label} · {String(m.role).replace("_", " ")}</span><span className="mt-1 block text-sm leading-6 text-[#6b7872]">{blurb[m.role]}</span></span>{busy === m.id ? <Clock3 className="animate-spin" size={18} /> : <ChevronRight size={18} />}</button>)}</div>
    <p className="mt-7 text-center"><button onClick={async () => { await api("/api/auth", { method: "DELETE" }); await api("/api/session", { method: "DELETE" }); router.push("/signin"); }} className="text-sm font-semibold text-[#5d42e6]">Sign out</button></p><p className="mt-3 text-center text-xs leading-5 text-[#7b8881]">Demo limitation: Azentio Entra ID SSO is not connected; demo tenants are provisioned to signed-in users and staff roles are allow-listed.</p></div></main>;
}


function WorkspaceRouter({ path }: { path: string }) {
  const [session, setSession] = useState<Json | null>(null), [loading, setLoading] = useState(true);
  useEffect(() => { api("/api/portal?scope=session").then(setSession).catch(() => setSession(null)).finally(() => setLoading(false)); }, [path]);
  if (loading) return <Loading />;
  if (!session) return <main className="grid min-h-[70vh] place-items-center p-6"><div className="surface max-w-lg p-9 text-center"><LockKeyhole className="mx-auto text-[#5d42e6]" size={34} /><h1 className="mt-5 text-2xl font-semibold">Select a workspace to continue</h1><p className="mt-2 text-[#66736d]">Protected routes require a server-verified membership.</p><Link className="btn-primary mt-6" href="/login">Choose workspace <ArrowRight size={15} /></Link></div></main>;
  const allowed = path === "/learning" || (session.role === "client" && path.startsWith("/client/") && (path !== "/client/members" || session.memberRole === "client_admin")) || (session.role === "moderator" && ["/moderation", "/moderation/themes"].includes(path)) || (["employee", "product_owner"].includes(session.role) && path.startsWith("/employee/") && (!["/employee/ideas", "/employee/entitlements"].includes(path) || session.memberRole === "product_owner") && (path !== "/employee/content" || ["content_publisher", "product_owner"].includes(session.memberRole)));
  const view = !allowed ? <AccessDenied /> : path === "/client/observations" ? <Observations session={session} /> : path === "/client/members" ? <Members /> : path === "/client/learning" || path === "/learning" ? <Learning session={session} /> : path === "/client/sandbox" || path === "/employee/playground" ? <Playground session={session} /> : path === "/moderation" ? <Moderation /> : path === "/moderation/themes" ? <Themes /> : path === "/client/updates" || path === "/employee/updates" || path === "/employee/content" ? <Updates session={session} /> : path === "/employee/entitlements" ? <Entitlements /> : path === "/employee/lab" ? <Lab /> : path === "/employee/ideas" ? <Ideas /> : path.startsWith("/employee") ? <EmployeeDashboard session={session} /> : <ClientDashboard session={session} />;
  return <div className="mx-auto flex max-w-[1440px]"><SideNav session={session} path={path} /><main className="min-w-0 flex-1 px-5 pb-24 pt-8 md:px-8 lg:px-10 lg:pb-8"><div className="mb-4 flex justify-end"><NotificationBell /></div>{view}</main></div>;
}


function SideNav({ session, path }: { session: Json; path: string }) {
  const links: [string, string, typeof Gauge][] = session.role === "client"
    ? [["/client/dashboard", "Overview", Gauge], ["/client/sandbox", "Entitled sandbox", FlaskConical], ["/client/observations", "My observations", MessageSquareText], ["/client/learning", "Collective learning", BookOpen], ...(session.memberRole === "client_admin" ? [["/client/members", "Members", Users] as [string, string, typeof Gauge]] : []), ["/client/updates", "Updates", Bell]]
    : session.role === "moderator" ? [["/moderation", "Review queue", ClipboardCheck], ["/moderation/themes", "Themes", Target], ["/learning", "Published learning", BookOpen]]
    : [["/employee/dashboard", "Innovation home", Gauge], ["/employee/playground", "Playground", FlaskConical], ["/employee/lab", "Experiments & teams", Users], ["/employee/updates", "Updates", Bell], ...(session.memberRole === "product_owner" ? [["/employee/ideas", "Improvements", Lightbulb], ["/employee/entitlements", "Entitlements", Boxes]] as [string, string, typeof Gauge][] : []), ...(["content_publisher", "product_owner"].includes(session.memberRole) ? [["/employee/content", "Publish content", Send]] as [string, string, typeof Gauge][] : []), ["/learning", "Collective learning", BookOpen]];
  return <><nav aria-label="Workspace navigation" className="fixed inset-x-0 bottom-0 z-40 flex gap-1 overflow-x-auto border-t border-[#dce3dd] bg-[#f8faf7]/95 px-3 py-2 backdrop-blur lg:hidden">{links.map(([href, label, Icon]) => <Link key={href} href={href} className={`side-link shrink-0 whitespace-nowrap ${path === href ? "active" : ""}`}><Icon size={16} />{label}</Link>)}</nav><aside className="sticky top-[72px] hidden h-[calc(100vh-72px)] w-[245px] shrink-0 border-r border-[#dce3dd] bg-[#f1f4ef] p-5 lg:flex lg:flex-col"><div className="rounded-2xl border border-[#d8e0da] bg-white p-4"><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#809087]">Active workspace</div><div className="mt-2 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#e9f5ef] text-[#008d70]"><Building2 size={18} /></span><div className="min-w-0"><div className="truncate text-sm font-bold">{session.organization}</div><div className="text-xs capitalize text-[#75827b]">{String(session.memberRole).replace("_", " ")}</div></div></div></div><nav className="mt-7 grid gap-1">{links.map(([href, label, Icon]) => <Link key={href} href={href} className={`side-link ${path === href ? "active" : ""}`}><Icon size={17} />{label}</Link>)}</nav><div className="mt-auto rounded-2xl bg-[#172720] p-4 text-white"><div className="flex items-center gap-2 text-xs text-[#a9bdb3]"><ShieldCheck size={14} /> Governed session</div><p className="mt-2 text-xs leading-5 text-[#c7d4ce]">Membership, tenant and audience checks run on every protected request.</p></div></aside></>;
}


function ClientDashboard({ session }: { session: Json }) {
  const [products, setProducts] = useState<Json[] | null>(null), [obsCount, setObsCount] = useState(0);
  useEffect(() => { api("/api/portal?scope=entitlements").then(r => setProducts(r.products)).catch(() => setProducts([])); api("/api/portal?scope=observations").then(r => setObsCount(r.observations.length)).catch(() => undefined); }, []);
  return <div><WorkspaceHead eyebrow="Client workspace" title={`Welcome, ${session.organization}.`} text="Your entitled intelligence products, private contributions and approved market learning — in one governed view." />
    <div className="mt-7 grid gap-4 sm:grid-cols-3"><Metric label="Entitled products" value={String(products?.length ?? "–")} icon={<Boxes />} note="Server-verified" /><Metric label="Your observations" value={String(obsCount)} icon={<MessageSquareText />} note="Tenant private" /><Metric label="Role" value={String(session.memberRole).replace("client_", "")} icon={<ShieldCheck />} note="From membership" /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><section className="surface p-6"><div className="kicker">Entitled products</div>
      {products && products.length === 0 && <Empty icon={<Boxes />} title="No products enabled" text="Ask Azentio to enable a product for your organisation." />}
      <div className="mt-4 grid gap-3">{(products ?? []).map(p => <div key={p.id} className="flex items-center justify-between rounded-2xl bg-[#edf5f1] p-5"><div className="flex items-center gap-4"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-[#008d70] text-white"><BarChart3 /></span><div><div className="font-bold">{p.name}</div><Link href="/client/sandbox" className="mt-1 inline-flex items-center gap-2 text-sm font-bold text-[#006f58]">Open guided demo <ArrowRight size={14} /></Link></div></div><span className="status green">Active</span></div>)}</div></section>
      <section className="surface p-6"><div className="kicker">Contribution status</div><h2 className="mt-2 text-xl font-semibold">Your learning loop</h2><div className="mt-5 space-y-4"><Timeline label="Private draft" done /><Timeline label="Consent & submission" done /><Timeline label="Moderator review" /><Timeline label="Client update" /></div><Link href="/client/observations" className="btn-secondary mt-6 w-full justify-center">Manage observations</Link></section></div></div>;
}


const STATUS_HELP: Record<string, string> = { draft: "Private draft", submitted: "Awaiting moderation", clarification_requested: "Moderator asked for clarification", rejected: "Not approved", published: "Shared with community", reported: "Under investigation", withdrawn: "Withdrawn" };

function Observations({ session }: { session: Json }) {
  const [rows, setRows] = useState<Json[]>([]), [notice, setNotice] = useState(""), [error, setError] = useState(""), [editing, setEditing] = useState<Json | null>(null), [history, setHistory] = useState<{ id: string; items: Json[] } | null>(null);
  const load = () => api("/api/portal?scope=observations").then(r => setRows(r.observations)).catch(x => setError(x.message));
  useEffect(() => { load(); }, []);
  async function send(form: HTMLFormElement, submit: boolean) {
    setError(""); setNotice(""); const f = new FormData(form);
    const body: Json = { ...Object.fromEntries(f), action: editing ? "update_observation" : "create_observation", submit, processingConsent: f.get("processingConsent") === "on", allowAttribution: f.get("allowAttribution") === "on", allowModelTraining: false };
    if (editing) body.observationId = editing.id; else body.idempotencyKey = crypto.randomUUID();
    try { const r = await api("/api/portal", { method: "POST", body: JSON.stringify(body) }); setNotice(`${r.observation_id} · ${r.status}${r.privacy_flags?.length ? ` · flagged for moderator: ${r.privacy_flags.join(", ")}` : ""}`); setEditing(null); form.reset(); load(); } catch (x) { setError((x as Error).message); }
  }
  async function act(action: string, id: string, extra: Json = {}) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action, observationId: id, ...extra }) }); setNotice(`${id}: ${action} done.`); load(); } catch (x) { setError((x as Error).message); } }
  async function showHistory(id: string) { try { const r = await api(`/api/portal?scope=consents&id=${id}`); setHistory({ id, items: r.consents }); } catch (x) { setError((x as Error).message); } }
  const v = (k: string, d: string) => (editing?.[k] as string | undefined) ?? d;
  return <div key={editing?.id ?? "new"}><WorkspaceHead eyebrow="Private contributions" title="Market observations" text={`Private records are visible only to their author; organisation records to members of ${session.organization}. Community sharing is a separate, moderated action.`} action={<span className="status"><LockKeyhole size={12} /> Tenant private</span>} />{notice && <div className="mt-6"><Alert text={notice} success /></div>}{error && <div className="mt-6"><Alert text={error} /></div>}
    <div className="mt-7 grid gap-6 xl:grid-cols-[1.05fr_.95fr]"><form className="surface p-6" onSubmit={e => { e.preventDefault(); send(e.currentTarget, true); }}><div className="flex items-center justify-between"><h2 className="text-xl font-semibold">{editing ? `Edit ${editing.id}` : "New observation"}</h2>{editing ? <button type="button" onClick={() => setEditing(null)} className="text-xs font-bold text-[#a34d43]">Cancel edit</button> : <span className="text-xs text-[#748179]">Synthetic data only</span>}</div>
      <div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Offering" name="offering" value={v("offering", "Financial Analysis Intelligence")} /><Field label="Topic" name="title" value={v("title", "Seasonal SME cash-flow analysis")} /><Field label="Industry" name="industry" value={v("industry", "Banking")} /><Field label="Region" name="region" value={v("region", "India")} /><Field label="Observation period" name="observationPeriod" value={v("observationPeriod", "2026-Q3")} /><Field label="Evidence type" name="evidenceType" value={v("evidenceType", "Synthetic market observation")} /><SelectField label="Confidence" name="confidence" options={["Medium", "High", "Low"]} value={v("confidence", "Medium")} /><SelectField label="Visibility intent" name="sharingIntent" options={["propose_community", "organization", "private"]} value={v("sharingIntent", "propose_community")} /></div>
      <div className="mt-4"><Field label="What did you observe?" name="description" area value={v("description", "Seasonal cash-flow variation is not reflected in the current analysis.")} /></div>
      <div className="mt-4 rounded-2xl border border-[#eadba9] bg-[#fff9e9] p-4 text-sm leading-6 text-[#6d5d2e]"><CircleAlert className="mr-2 inline" size={16} />Do not include identities, account numbers, credentials or confidential terms. Obvious matches are flagged and need explicit moderator acknowledgement.</div>
      <label className="mt-5 flex gap-3 text-sm"><input type="checkbox" name="processingConsent" className="mt-1" /><span>I consent to storing and processing this contribution (required to submit). Publication still requires moderation.</span></label><label className="mt-3 flex gap-3 text-sm"><input type="checkbox" name="allowAttribution" className="mt-1" /><span>Allow organisation attribution if the moderator approves it.</span></label><p className="mt-3 text-xs text-[#75827b]">Model training use is off and not offered in this prototype.</p>
      <div className="mt-6 flex flex-wrap gap-3"><button type="button" onClick={e => send(e.currentTarget.form!, false)} className="btn-secondary">{editing ? "Save draft changes" : "Save private draft"}</button><button className="btn-primary" type="submit">{editing ? "Resubmit for review" : "Submit for review"} <Send size={15} /></button></div></form>
      <section><div className="mb-4 flex items-center justify-between"><h2 className="text-lg font-semibold">Your records</h2><span className="text-sm text-[#728078]">{rows.length} total</span></div><div className="space-y-3">{rows.length ? rows.map(r => <article key={r.id} className="surface p-5"><div className="flex items-start justify-between gap-3"><div><div className="text-xs font-bold text-[#7b8881]">{r.id} · v{r.version}</div><h3 className="mt-1 font-bold">{r.title}</h3></div><span className={`status ${r.status === "published" ? "green" : ""}`}>{STATUS_HELP[r.status] ?? r.status}</span></div><p className="mt-3 line-clamp-2 text-sm leading-6 text-[#68766f]">{r.description}</p>{r.privacyFlags && <p className="mt-2 text-xs font-semibold text-[#8a6d1f]">Flagged: {r.privacyFlags}</p>}
        <div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-[#e5e9e5] pt-4 text-xs text-[#75827b]"><span>{String(r.sharingIntent).replace("_", " ")}</span><span className="flex flex-wrap gap-3 font-bold">
          {["draft", "clarification_requested", "published"].includes(r.status) && <button onClick={() => setEditing(r)} className="text-[#5d42e6]">{r.status === "published" ? "Edit (renewed review)" : "Edit"}</button>}
          <button onClick={() => showHistory(r.id)} className="text-[#006f58]">Consent history</button>
          {!["withdrawn", "rejected"].includes(r.status) && <button onClick={() => act("withdraw", r.id)} className="text-[#a34d43]">Withdraw</button>}</span></div>
        {history && history.id === r.id && <ul className="mt-3 space-y-1 border-t border-[#e5e9e5] pt-3 text-xs text-[#5f6d66]">{history.items.map(h => <li key={h.id}>{h.createdAt} · {String(h.type).replace("_", " ")} · <b>{h.state}</b> · policy {h.policyVersion}</li>)}<li className="text-[#8a958f]">Visible to your organisation; moderators see processing and sharing only.</li></ul>}</article>) : <Empty icon={<MessageSquareText />} title="No observations yet" text="Create a private draft to begin." />}</div></section></div></div>;
}


function Moderation() {
  const [rows, setRows] = useState<Json[]>([]), [reports, setReports] = useState<Json[]>([]), [themes, setThemes] = useState<Json[]>([]), [selected, setSelected] = useState<Json | null>(null), [notice, setNotice] = useState(""), [error, setError] = useState("");
  const load = () => {
    api("/api/portal?scope=observations").then(r => { setRows(r.observations); setSelected(r.observations[0] ?? null); }).catch(x => setError(x.message));
    api("/api/portal?scope=reports").then(r => setReports(r.reports)).catch(() => undefined);
    api("/api/portal?scope=learning").then(r => setThemes(r.themes)).catch(() => undefined);
  };
  useEffect(() => { load(); }, []);
  async function seed() { try { const r = await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "seed_scenario" }) }); setNotice(`Scenario ready (${r.created} new synthetic records). Withdrawn records are never revived.`); load(); } catch (x) { setError((x as Error).message); } }
  async function decide(form: HTMLFormElement, decision: string) {
    if (!selected) return; const f = new FormData(form); setError("");
    const body: Json = { action: "moderate", observationId: selected.id, decision, reason: f.get("reason"), acknowledgeFlags: f.get("ack") === "on" };
    if (decision === "publish") { body.approvedText = f.get("approvedText"); if (f.get("themeId")) body.themeId = f.get("themeId"); }
    try { const r = await api("/api/portal", { method: "POST", body: JSON.stringify(body) }); setNotice(`${r.publication_id ?? selected.id} → ${r.status}${r.version ? ` v${r.version}` : ""}`); load(); } catch (x) { setError((x as Error).message); }
  }
  async function resolve(id: string, outcome: string) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "resolve_report", reportId: id, outcome }) }); load(); } catch (x) { setError((x as Error).message); } }
  return <div><WorkspaceHead eyebrow="Learning governance" title="Moderation desk" text="Only community-sharing proposals appear here. Compare the private source with the de-identified copy; shared payloads never carry tenant metadata." action={<button onClick={seed} className="btn-secondary"><Sparkles size={15} /> Load 3-org scenario</button>} />{notice && <div className="mt-6"><Alert text={notice} success /></div>}{error && <div className="mt-6"><Alert text={error} /></div>}
    {reports.length > 0 && <section className="surface mt-6 p-5"><div className="kicker">Open reports · publications are temporarily unpublished</div>{reports.map(r => <div key={r.id} className="mt-3 flex flex-wrap items-center justify-between gap-3 text-sm"><span><b>{r.publicationId}</b> — {r.reason}</span><span className="flex gap-3 font-bold"><button onClick={() => resolve(r.id, "restore")} className="text-[#006f58]">Restore</button><button onClick={() => resolve(r.id, "withdraw")} className="text-[#a34d43]">Withdraw</button></span></div>)}</section>}
    <div className="mt-7 grid gap-5 xl:grid-cols-[310px_1fr]"><section className="surface p-4"><div className="mb-3 px-2 text-xs font-bold uppercase tracking-[.14em] text-[#738179]">Review queue · {rows.length}</div>{rows.length ? rows.map(r => <button key={r.id} onClick={() => setSelected(r)} className={`queue-item ${selected?.id === r.id ? "active" : ""}`}><div className="flex items-center justify-between"><span className="text-xs font-bold text-[#78857e]">{r.id}</span><span className={`h-2 w-2 rounded-full ${r.privacyFlags ? "bg-[#d9534f]" : "bg-[#efad37]"}`} /></div><div className="mt-2 font-bold">{r.title}</div><div className="mt-1 text-xs text-[#78857e]">{r.offering}</div></button>) : <Empty icon={<ClipboardCheck />} title="Queue is clear" text="Client community proposals will appear here." />}</section>
      {selected ? <form key={selected.id} onSubmit={e => e.preventDefault()} className="surface overflow-hidden"><div className="grid md:grid-cols-2"><div className="border-b border-[#e0e6e1] bg-[#f5f6f3] p-6 md:border-b-0 md:border-r"><div className="kicker">Private source · restricted</div><h2 className="mt-3 text-xl font-semibold">{selected.title}</h2><div className="mt-5 grid grid-cols-2 gap-3 text-sm"><Fact k="Industry" v={selected.industry} /><Fact k="Region" v={selected.region} /><Fact k="Period" v={selected.observationPeriod} /><Fact k="Confidence" v={selected.confidence} /></div><div className="mt-5 rounded-2xl bg-white p-4 text-sm leading-6 text-[#5f6d66]">{selected.description}</div>{selected.privacyFlags && <div className="mt-4 rounded-xl bg-[#fff0ed] p-3 text-xs text-[#8f443b]"><b>Privacy scan flagged:</b> {selected.privacyFlags}<label className="mt-2 flex gap-2"><input type="checkbox" name="ack" /> I have reviewed the flagged material</label></div>}</div>
        <div className="p-6"><div className="kicker text-[#5d42e6]">Proposed shared copy</div><div className="mt-5"><Field label="Approved text" name="approvedText" area value="Seasonal SME cash flows may require additional context during financial analysis." /></div><div className="mt-4"><Field label="Decision reason" name="reason" value="Identifying and overly specific details removed" /></div>
          <label className="field mt-4"><span>Link to theme (optional)</span><select name="themeId" defaultValue=""><option value="">No theme</option>{themes.map(t => <option key={t.id} value={t.id}>{t.title}</option>)}<option value="THM-SEASONALITY">Seasonality context</option></select></label>
          <div className="mt-6 grid gap-2 sm:grid-cols-3"><button type="button" onClick={e => decide(e.currentTarget.form!, "publish")} className="btn-primary justify-center"><Check size={15} /> Publish</button><button type="button" onClick={e => decide(e.currentTarget.form!, "clarify")} className="btn-secondary justify-center">Ask to clarify</button><button type="button" onClick={e => decide(e.currentTarget.form!, "reject")} className="btn-secondary justify-center">Reject</button></div></div></div></form> : <div className="surface grid min-h-[480px] place-items-center"><Empty icon={<FileSearch />} title="Select a submission" text="The private source and proposed public copy will appear side by side." /></div>}</div></div>;
}


function Learning({ session }: { session: Json }) {
  const [data, setData] = useState<Json | null>(null), [error, setError] = useState(""), [filters, setFilters] = useState<Record<string, string>>({}), [answer, setAnswer] = useState<Json | null>(null), [notice, setNotice] = useState("");
  const load = (f = filters) => { const qs = new URLSearchParams(Object.entries(f).filter(([, v]) => v)).toString(); api(`/api/portal?scope=learning&${qs}`).then(setData).catch(x => setError(x.message)); };
  useEffect(() => { load(); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  const setF = (k: string, v: string) => { const next = { ...filters, [k]: v }; setFilters(next); load(next); setAnswer(null); };
  async function ask(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); const q = new FormData(e.currentTarget).get("question"); try { setAnswer(await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "aira", question: q, filters }) })); } catch (x) { setError((x as Error).message); } }
  async function report(id: string) { const reason = window.prompt("Why should this be reviewed?"); if (!reason) return; try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "report", publicationId: id, reason }) }); setNotice(`${id} reported and temporarily unpublished pending review.`); load(); } catch (x) { setError((x as Error).message); } }
  const [open, setOpen] = useState(""), [comments, setComments] = useState<Json[]>([]);
  async function bookmark(id: string) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "add_bookmark", kind: "publication", ref: id, label: id }) }); setNotice(`${id} bookmarked.`); } catch (x) { setError((x as Error).message); } }
  async function saveSearch() { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "add_bookmark", kind: "search", ref: new URLSearchParams(Object.entries(filters).filter(([, v]) => v)).toString() || "all", label: "Saved search" }) }); setNotice("Search saved."); } catch (x) { setError((x as Error).message); } }
  async function toggleComments(id: string) { if (open === id) { setOpen(""); return; } setOpen(id); try { setComments((await api(`/api/portal?scope=comments&id=${id}`)).comments); } catch (x) { setError((x as Error).message); } }
  async function addComment(e: React.FormEvent<HTMLFormElement>, id: string) { e.preventDefault(); const f = new FormData(e.currentTarget); try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "add_comment", publicationId: id, body: f.get("body") }) }); e.currentTarget.reset(); setComments((await api(`/api/portal?scope=comments&id=${id}`)).comments); } catch (x) { setError((x as Error).message); } }
  const themes: Json[] = data?.themes ?? [];
  return <div><WorkspaceHead eyebrow="Approved community evidence" title="Collective learning" text="Search, synthesis and counts operate on moderated shared copies only. Private drafts never enter this view." action={<span className="flex gap-2"><button onClick={saveSearch} className="btn-secondary">Save search</button><button onClick={() => load()} className="btn-secondary"><Search size={15} /> Refresh evidence</button></span>} />{error && <div className="mt-6"><Alert text={error} /></div>}{notice && <div className="mt-6"><Alert text={notice} success /></div>}
    <div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{(["offering", "industry", "region", "period", "topic"] as const).map(k => <label key={k} className="field"><span className="capitalize">{k}</span><input value={filters[k] ?? ""} onChange={e => setF(k, e.target.value)} placeholder="Any" /></label>)}</div>
    {data && <><div className="mt-7 grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><section className="surface p-6"><div className="kicker">Theme dashboard · threshold applied per theme and filter set</div>{themes.length ? themes.map(t => <div key={t.id} className="mt-4 border-t border-[#e5e9e5] pt-4 first:border-0 first:pt-0"><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="text-2xl font-semibold">{t.title}</h2><span className="status green">{t.distinct_organizations} distinct organisations</span></div><p className="mt-4 max-w-2xl text-[17px] leading-7 text-[#53625b]">{t.summary}</p><div className="mt-4 flex flex-wrap gap-2">{t.supporting_publications.map((id: string) => <span className="source light" key={id}>{id}</span>)}</div><div className="mt-4 rounded-2xl border border-[#eadba9] bg-[#fff9e9] p-4 text-sm text-[#6d5d2e]"><CircleAlert className="mr-2 inline" size={16} />{t.warning}</div></div>) : <Empty icon={<Eye />} title="Aggregation safeguard active" text="At least three distinct contributing organisations are required per theme. Withdrawn evidence is excluded immediately." />}</section>
      <section className="rounded-[24px] bg-[#172720] p-6 text-white"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.14em] text-[#9ec4b4]"><Bot size={16} /> AIRA · approved retrieval · deterministic fallback</div>
        <form onSubmit={ask} className="mt-5 flex gap-2"><input name="question" required minLength={5} defaultValue="What recurring seasonality concern exists?" className="min-w-0 flex-1 rounded-xl bg-white/10 px-3 py-2 text-sm text-white outline-none" /><button className="btn-primary" type="submit">Ask</button></form>
        {answer && <div className="mt-5"><p className="leading-7 text-[#d6e0db]">{answer.answer}</p>{answer.status === "answered" ? <><div className="mt-4 flex flex-wrap gap-2">{answer.references.map((id: string) => <span className="source" key={id}>{id}</span>)}</div><div className="mt-5 border-t border-white/10 pt-4 text-xs text-[#9eb0a8]">Suggested improvement<div className="mt-1 font-semibold text-[#c9ffea]">{answer.suggestedImprovement}</div></div></> : <p className="mt-3 text-xs text-[#9eb0a8]">No references returned.</p>}</div>}
        <div className="mt-6 flex items-center gap-2 text-xs text-[#96aaa1]"><ShieldCheck size={14} /> No private source material sent to AI</div></section></div>
      <section className="mt-6"><div className="mb-4 flex items-center justify-between"><h2 className="text-lg font-semibold">Approved evidence</h2><span className="text-sm text-[#748179]">{data.publications.length} publications</span></div><div className="grid gap-4 lg:grid-cols-3">{data.publications.map((p: Json) => <article className="surface p-5" key={p.id}><div className="flex items-center justify-between"><span className="source light">{p.id} · v{p.version}</span><span className="status green">approved</span></div><p className="mt-5 text-[15px] leading-7 text-[#526159]">{p.approvedText}</p><div className="mt-5 flex items-center justify-between border-t border-[#e3e8e4] pt-4 text-xs text-[#76837c]"><span>{p.industry} · {p.region} · {p.observationPeriod}</span><span className="flex gap-3 font-bold"><button onClick={() => bookmark(p.id)} className="text-[#006f58]">Bookmark</button><button onClick={() => toggleComments(p.id)} className="text-[#5d42e6]">Comments</button>{session.role !== "moderator" && <button onClick={() => report(p.id)} className="text-[#a34d43]">Report</button>}</span></div>{open === p.id && <div className="mt-3 border-t border-[#e3e8e4] pt-3 text-xs">{comments.map(c => <p key={c.id} className="mb-1"><b>{c.authorLabel}:</b> {c.body}</p>)}<form onSubmit={e => addComment(e, p.id)} className="mt-2 flex gap-2"><input name="body" required minLength={2} placeholder="Add a comment" className="min-w-0 flex-1 rounded-lg border border-[#d5ddd7] px-2 py-1" /><button className="btn-secondary" type="submit">Post</button></form></div>}</article>)}</div></section></>}</div>;
}


function EmployeeDashboard({ session }: { session: Json }) { return <div><WorkspaceHead eyebrow="Employee innovation" title="Welcome to the AI Lab." text="Explore governed experiments, assigned improvement work and internal learning without exposing employee-only material to clients." /><div className="mt-7 grid gap-4 sm:grid-cols-3"><Metric label="Active experiments" value="06" icon={<FlaskConical />} note="Internal only" /><Metric label="Assigned ideas" value="02" icon={<Lightbulb />} note="Evidence linked" /><Metric label="Live sessions" value="01" icon={<Play />} note="Employee audience" /></div><div className="mt-6 grid gap-5 lg:grid-cols-2"><Link href="/employee/playground" className="surface group p-7"><span className="product-icon mint"><FlaskConical /></span><h2 className="mt-8 text-2xl font-semibold">Guided playground</h2><p className="mt-3 text-[#68766f]">Run a deterministic seasonal cash-flow explanation with synthetic inputs.</p><span className="mt-7 inline-flex items-center gap-2 text-sm font-bold text-[#008d70]">Launch experiment <ArrowRight size={15} /></span></Link><Link href="/employee/ideas" className={`surface group p-7 ${session.memberRole === "product_owner" ? "" : "hidden"}`}><span className="product-icon violet"><Target /></span><h2 className="mt-8 text-2xl font-semibold">Improvement tracker</h2><p className="mt-3 text-[#68766f]">Convert an approved cross-client theme into accountable product work.</p><span className="mt-7 inline-flex items-center gap-2 text-sm font-bold text-[#5d42e6]">Review ideas <ArrowRight size={15} /></span></Link></div></div>; }

function Playground({ session }: { session: Json }) {
  const [result, setResult] = useState<Json | null>(null), [seasonality, setSeasonality] = useState("42"), [cycle, setCycle] = useState("Festival retail"), [offering, setOffering] = useState("Financial Analysis Intelligence"), [products, setProducts] = useState<Json[] | null>(null), [error, setError] = useState("");
  useEffect(() => { if (session.role === "client") api("/api/portal?scope=entitlements").then(r => { setProducts(r.products); if (r.products[0]) setOffering(r.products[0].name); }).catch(x => setError(x.message)); }, [session.role]);
  async function run() { setError(""); try { setResult(await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "sandbox_run", offering, cycle, seasonality: Number(seasonality) }) })); } catch (x) { setError((x as Error).message); setResult(null); } }
  if (session.role === "client" && products?.length === 0) return <div><WorkspaceHead eyebrow="Synthetic sandbox" title="Entitled sandbox" text="Sandbox access is checked against your organisation's enabled products on every run." /><div className="surface mt-7"><Empty icon={<Boxes />} title="No products enabled" text="Your organisation has no enabled product entitlements." /></div></div>;
  return <div><WorkspaceHead eyebrow="Synthetic sandbox" title="Financial analysis playground" text="A deterministic demonstration — not an approved credit decision, production model or client-data analysis." action={<span className="status"><FlaskConical size={12} /> Sample data</span>} />{error && <div className="mt-6"><Alert text={error} /></div>}
    <div className="mt-7 grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><section className="surface p-6"><h2 className="text-lg font-semibold">Scenario inputs</h2><div className="mt-6 grid gap-5">{session.role === "client" && products && <SelectField label="Product" name="offering" value={offering} onChange={setOffering} options={products.map(p => p.name)} />}<SelectField label="Operating cycle" name="cycle" value={cycle} onChange={setCycle} options={["Festival retail", "Agricultural harvest", "Tourism peak"]} /><label className="field"><span>Seasonal revenue share · {seasonality}%</span><input type="range" min="10" max="80" value={seasonality} onChange={e => setSeasonality(e.target.value)} /></label></div><button onClick={run} className="btn-primary mt-7 w-full justify-center"><Play size={15} /> Run synthetic analysis</button></section>
      <section className="surface p-6">{result ? <div><div className="flex items-center justify-between"><div className="kicker">Simulated result</div><span className="status green"><Check size={12} /> Complete</span></div><div className="mt-6 rounded-2xl bg-[#172720] p-6 text-white"><div className="text-sm text-[#9fb3aa]">Context adjustment</div><div className="mt-2 text-3xl font-semibold tracking-[-.04em]">{result.headline}</div><p className="mt-4 leading-7 text-[#d0dcd6]">{result.explanation}</p></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><Fact k="Evidence" v="Synthetic ledger" /><Fact k="Mode" v={result.mode} /><Fact k="Decision" v="Human review" /></div><div className="mt-5 rounded-xl bg-[#fff9e9] p-4 text-xs leading-5 text-[#6d5d2e]">{result.disclaimer}</div></div> : <Empty icon={<Gauge />} title="Ready to run" text="Configure a synthetic operating cycle and run the deterministic explanation." />}</section></div></div>;
}


function Ideas() {
  const [rows, setRows] = useState<Json[]>([]), [learning, setLearning] = useState<Json | null>(null), [notice, setNotice] = useState(""), [error, setError] = useState("");
  const load = () => { api("/api/portal?scope=improvements").then(r => setRows(r.improvements)).catch(x => setError(x.message)); api("/api/portal?scope=learning").then(setLearning).catch(() => undefined); };
  useEffect(() => { load(); }, []);
  async function seed() { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "seed_scenario" }) }); setNotice("Approved evidence scenario loaded."); load(); } catch (x) { setError((x as Error).message); } }
  async function create(e: React.FormEvent<HTMLFormElement>, theme: Json) { e.preventDefault(); setError(""); const f = new FormData(e.currentTarget); try { const r = await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "create_improvement", title: f.get("title"), problemStatement: f.get("problemStatement"), proposedOutcome: f.get("proposedOutcome"), owner: f.get("owner"), priority: f.get("priority"), themeId: theme.id, evidenceIds: theme.supporting_publications }) }); setNotice(`${r.id} created and linked to ${r.evidenceIds.join(", ")}.`); load(); } catch (x) { setError((x as Error).message); } }
  async function advance(id: string, status: string, f: FormData) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "improvement_status", improvementId: id, status, internalNote: f.get("internalNote") || undefined, clientUpdate: f.get("clientUpdate") || undefined }) }); setNotice(`${id} → ${status}`); load(); } catch (x) { setError((x as Error).message); } }
  const NEXT: Record<string, string[]> = { "Under review": ["Planned", "Declined"], Planned: ["In progress", "Declined"], "In progress": ["Released", "Planned"], Released: [], Declined: [] };
  const themes: Json[] = learning?.themes ?? [];
  return <div><WorkspaceHead eyebrow="Evidence to action" title="Product improvement tracker" text="Create work only from approved evidence meeting the three-organisation threshold. Under review is a decision state, not a delivery promise." action={<button onClick={seed} className="btn-secondary"><Sparkles size={15} /> Load scenario</button>} />{notice && <div className="mt-6"><Alert text={notice} success /></div>}{error && <div className="mt-6"><Alert text={error} /></div>}
    <div className="mt-7 grid gap-5 xl:grid-cols-[.85fr_1.15fr]"><section className="space-y-4">{themes.length ? themes.map(t => <form key={t.id} onSubmit={e => create(e, t)} className="surface p-6"><div className="kicker">Approved theme · {t.distinct_organizations} organisations</div><h2 className="mt-3 text-2xl font-semibold">{t.title}</h2><p className="mt-3 leading-7 text-[#64726b]">{t.summary}</p><div className="mt-4 flex flex-wrap gap-2">{t.supporting_publications.map((id: string) => <span key={id} className="source light">{id}</span>)}</div><div className="mt-5 grid gap-3"><Field label="Title" name="title" value={t.suggested_improvement || t.title} /><Field label="Problem statement" name="problemStatement" area value={t.summary} /><Field label="Proposed outcome" name="proposedOutcome" value="Explain like-for-like seasonal comparisons with traceable evidence." /><Field label="Owner" name="owner" value="Financial Intelligence product team" /><SelectField label="Priority" name="priority" options={["High", "Medium", "Low", "Critical"]} /></div><button className="btn-primary mt-6 w-full justify-center" type="submit"><Plus size={16} /> Create improvement idea</button></form>) : <div className="surface p-6"><Empty icon={<Eye />} title="No theme meets the threshold" text="Load the approved scenario or wait for three organisations to contribute." /></div>}</section>
      <section><div className="mb-4 flex items-center justify-between"><h2 className="text-lg font-semibold">Tracked work</h2><span className="text-sm text-[#748179]">{rows.length} ideas</span></div>{rows.length ? <div className="space-y-3">{rows.map(r => <article className="surface p-5" key={r.id}><div className="flex flex-wrap items-start justify-between gap-3"><div><span className="text-xs font-bold text-[#7a8780]">{r.id}</span><h3 className="mt-1 text-lg font-bold">{r.title}</h3></div><span className="status violet">{r.status}</span></div><p className="mt-3 text-sm leading-6 text-[#68766f]">{r.problemStatement}</p><div className="mt-5 grid gap-3 border-t border-[#e3e8e4] pt-4 text-xs sm:grid-cols-3"><Fact k="Owner" v={r.owner} /><Fact k="Priority" v={r.priority} /><Fact k="Evidence" v={r.evidenceIds} /></div>
        {(r.updates ?? []).length > 0 && <ul className="mt-4 space-y-1 text-xs text-[#5f6d66]">{r.updates.map((u: Json) => <li key={u.id}><b className="uppercase">{u.audience}</b> · {u.body}</li>)}</ul>}
        {NEXT[r.status]?.length > 0 && <form className="mt-4 grid gap-2 border-t border-[#e3e8e4] pt-4" onSubmit={e => e.preventDefault()}><input name="internalNote" placeholder="Internal note (employees only)" className="rounded-lg border border-[#d5ddd7] px-3 py-2 text-xs" /><input name="clientUpdate" placeholder="Client-visible update (notifies contributors)" className="rounded-lg border border-[#d5ddd7] px-3 py-2 text-xs" /><div className="flex flex-wrap gap-2">{NEXT[r.status].map(s => <button key={s} type="button" onClick={e => advance(r.id, s, new FormData(e.currentTarget.form!))} className="btn-secondary">{s}</button>)}</div></form>}</article>)}</div> : <Empty icon={<Lightbulb />} title="No tracked ideas" text="Load the approved scenario, then create an evidence-linked improvement." />}</section></div></div>;
}

function SignIn() {
  const router = useRouter(), [mode, setMode] = useState<"signin" | "signup">("signin"), [error, setError] = useState(""), [busy, setBusy] = useState(false);
  async function submit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault(); setError(""); setBusy(true); const f = new FormData(e.currentTarget);
    try { await api("/api/auth", { method: "POST", body: JSON.stringify({ mode, email: f.get("email"), password: f.get("password"), name: f.get("name") ?? undefined }) }); router.push("/login"); } catch (x) { setError((x as Error).message); setBusy(false); }
  }
  return <main className="px-5 py-14 md:px-9"><div className="mx-auto max-w-md"><div className="text-center"><Pill icon={<LockKeyhole size={13} />}>Secure access</Pill><h1 className="mt-6 text-4xl font-semibold tracking-[-.05em]">{mode === "signin" ? "Sign in" : "Create an account"}</h1></div>{error && <div className="mt-6"><Alert text={error} /></div>}
    <form onSubmit={submit} className="surface mt-8 grid gap-4 p-6">{mode === "signup" && <Field label="Name" name="name" value="" />}<Field label="Work email" name="email" type="email" value="" /><Field label="Password (10+ characters)" name="password" type="password" value="" /><button className="btn-primary justify-center" disabled={busy} type="submit">{mode === "signin" ? "Sign in" : "Create account"}</button><button type="button" onClick={() => setMode(mode === "signin" ? "signup" : "signin")} className="text-sm font-semibold text-[#5d42e6]">{mode === "signin" ? "Need an account? Create one" : "Have an account? Sign in"}</button></form>
    <p className="mt-5 text-center text-xs leading-5 text-[#7b8881]">An account alone grants no access. Workspaces come from memberships, invitations or the staff allow-list.</p></div></main>;
}

function NotificationBell() {
  const [data, setData] = useState<Json>({ notifications: [], unread: 0 }), [open, setOpen] = useState(false);
  const load = () => api("/api/portal?scope=notifications").then(setData).catch(() => undefined);
  useEffect(() => { load(); }, []);
  async function toggle() { const next = !open; setOpen(next); if (next && data.unread) { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "mark_read" }) }); setTimeout(load, 1500); } else load(); }
  return <div className="relative"><button onClick={toggle} className="btn-secondary relative" aria-label="Notifications"><Bell size={16} />{data.unread > 0 && <span className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-[#5d42e6] px-1 text-[10px] font-bold text-white">{data.unread}</span>}</button>
    {open && <div className="absolute right-0 z-40 mt-2 max-h-96 w-[320px] overflow-auto rounded-2xl border border-[#dce3dd] bg-white p-3 shadow-xl">{data.notifications.length ? data.notifications.map((n: Json) => <div key={n.id} className={`rounded-xl p-3 text-sm ${n.readAt ? "" : "bg-[#f1f7f4]"}`}><div className="text-[10px] font-bold uppercase tracking-[.1em] text-[#7b8881]">{String(n.event).replace("_", " ")}</div><p className="mt-1 leading-5 text-[#4a5952]">{n.message}</p></div>) : <p className="p-3 text-sm text-[#75827b]">No notifications yet.</p>}</div>}</div>;
}


function Members() {
  const [data, setData] = useState<Json>({ members: [], invitations: [] }), [error, setError] = useState(""), [notice, setNotice] = useState("");
  const load = () => api("/api/portal?scope=members").then(setData).catch(x => setError(x.message));
  useEffect(() => { load(); }, []);
  async function invite(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "invite_member", email: f.get("email"), role: f.get("role") }) }); setNotice("Invitation created. It is accepted when that person next signs in."); load(); } catch (x) { setError((x as Error).message); } }
  async function revoke(id: string) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "revoke_membership", membershipId: id }) }); load(); } catch (x) { setError((x as Error).message); } }
  return <div><WorkspaceHead eyebrow="Administration" title="Organisation members" text="Client administrators can invite and revoke client members. Employee, moderator and platform roles cannot be granted here." />{notice && <div className="mt-6"><Alert text={notice} success /></div>}{error && <div className="mt-6"><Alert text={error} /></div>}
    <div className="mt-7 grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><form onSubmit={invite} className="surface p-6"><h2 className="text-lg font-semibold">Invite a colleague</h2><div className="mt-5 grid gap-4"><Field label="Work email" name="email" type="email" value="" /><SelectField label="Role" name="role" options={["client_member", "client_admin"]} /></div><button className="btn-primary mt-6 w-full justify-center" type="submit">Send invitation</button></form>
      <section className="surface p-6"><h2 className="text-lg font-semibold">Members</h2><div className="mt-4 divide-y divide-[#e5e9e5]">{data.members.map((m: Json) => <div key={m.id} className="flex items-center justify-between py-3 text-sm"><div><div className="font-semibold">{m.email || m.id}</div><div className="text-xs text-[#75827b]">{String(m.role).replace("_", " ")} · {m.status}</div></div>{m.status === "active" && <button onClick={() => revoke(m.id)} className="text-xs font-bold text-[#a34d43]">Revoke</button>}</div>)}</div>{data.invitations.length > 0 && <><h3 className="mt-6 text-sm font-bold">Invitations</h3><ul className="mt-2 text-sm text-[#5f6d66]">{data.invitations.map((i: Json) => <li key={i.id}>{i.email} · {i.role} · {i.status}</li>)}</ul></>}</section></div><SupportAccess /></div>;
}


function PublicUpdates() {
  const [items, setItems] = useState<Json[]>([]);
  useEffect(() => { api("/api/public-content").then(r => setItems(r.items)).catch(() => undefined); }, []);
  if (!items.length) return null;
  return <section className="px-5 pb-16 md:px-9" aria-label="Latest updates"><div className="mx-auto max-w-[1340px]"><div className="kicker">Latest updates</div><div className="mt-4 grid gap-4 md:grid-cols-3">{items.slice(0, 3).map(i => <article key={i.id} className="surface p-5"><span className="status">{String(i.kind).replace("_", " ")}</span><h3 className="mt-3 font-bold">{i.title}</h3><p className="mt-2 text-sm leading-6 text-[#66736d]">{i.body}</p></article>)}</div></div></section>;
}

function Updates({ session }: { session: Json }) {
  const [items, setItems] = useState<Json[]>([]), [error, setError] = useState(""), [notice, setNotice] = useState("");
  const publisher = ["content_publisher", "product_owner"].includes(session.memberRole);
  const load = () => api("/api/portal?scope=content").then(r => setItems(r.items)).catch(x => setError(x.message));
  useEffect(() => { load(); }, []);
  async function create(e: React.FormEvent<HTMLFormElement>, publish: boolean) { e.preventDefault(); const form = e.currentTarget, f = new FormData(form); const orgId = f.get("orgId"); try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "create_content", kind: f.get("kind"), audience: f.get("audience"), orgId: orgId || undefined, title: f.get("title"), body: f.get("body"), publish }) }); setNotice(publish ? "Published." : "Draft saved."); form.reset(); load(); } catch (x) { setError((x as Error).message); } }
  async function setStatus(id: string, status: string) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "content_status", id, status }) }); load(); } catch (x) { setError((x as Error).message); } }
  return <div><WorkspaceHead eyebrow={session.role === "client" ? "Client updates" : "Employee updates"} title="Updates & knowledge" text="Release notes, broadcasts, knowledge articles and client resources — each visible only to its intended audience." />{notice && <div className="mt-6"><Alert text={notice} success /></div>}{error && <div className="mt-6"><Alert text={error} /></div>}
    <div className={`mt-7 grid gap-6 ${publisher ? "xl:grid-cols-[.8fr_1.2fr]" : ""}`}>{publisher && <form className="surface p-6" onSubmit={e => e.preventDefault()}><h2 className="text-lg font-semibold">New content</h2><div className="mt-5 grid gap-4"><SelectField label="Kind" name="kind" options={["release_note", "broadcast", "knowledge", "resource"]} /><SelectField label="Audience" name="audience" options={["client", "employee", "public"]} /><Field label="Organisation id (client resources only)" name="orgId" value="" required={false} /><Field label="Title" name="title" value="" /><Field label="Body" name="body" area value="" /></div><div className="mt-5 flex gap-3"><button type="submit" onClick={e => create({ ...e, currentTarget: e.currentTarget.form!, preventDefault: () => undefined } as unknown as React.FormEvent<HTMLFormElement>, false)} className="btn-secondary">Save draft</button><button type="button" onClick={e => create({ currentTarget: e.currentTarget.form!, preventDefault: () => undefined } as unknown as React.FormEvent<HTMLFormElement>, true)} className="btn-primary">Publish</button></div></form>}
      <section className="space-y-3">{items.length ? items.map(i => <article key={i.id} className="surface p-5"><div className="flex items-center justify-between gap-3"><span className="status">{String(i.kind).replace("_", " ")} · {i.audience}</span><span className={`status ${i.status === "published" ? "green" : ""}`}>{i.status}</span></div><h3 className="mt-3 font-bold">{i.title}</h3><p className="mt-2 text-sm leading-6 text-[#66736d]">{i.body}</p>{publisher && <div className="mt-3 flex gap-3 text-xs font-bold">{i.status !== "published" && <button onClick={() => setStatus(i.id, "published")} className="text-[#006f58]">Publish</button>}{i.status !== "archived" && <button onClick={() => setStatus(i.id, "archived")} className="text-[#a34d43]">Archive</button>}</div>}</article>) : <Empty icon={<Bell />} title="Nothing published yet" text="New updates for your audience will appear here." />}</section></div></div>;
}

function Entitlements() {
  const [data, setData] = useState<Json | null>(null), [error, setError] = useState("");
  const load = () => api("/api/portal?scope=entitlement_matrix").then(setData).catch(x => setError(x.message));
  useEffect(() => { load(); }, []);
  async function toggle(orgId: string, productId: string, enabled: boolean) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "set_entitlement", orgId, productId, enabled }) }); load(); } catch (x) { setError((x as Error).message); } }
  const on = (o: string, p: string) => (data?.entitlements ?? []).some((e: Json) => e.orgId === o && e.productId === p && e.status === "enabled");
  return <div><WorkspaceHead eyebrow="Administration" title="Product entitlements" text="Enable or disable products per organisation. Sandbox and resource access is checked against these rows on every request." />{error && <div className="mt-6"><Alert text={error} /></div>}
    {data && <div className="surface mt-7 overflow-x-auto p-6"><table className="w-full text-sm"><thead><tr className="text-left text-xs uppercase tracking-[.1em] text-[#7b8881]"><th className="pb-3">Organisation</th>{data.products.map((p: Json) => <th key={p.id} className="pb-3">{p.code}</th>)}</tr></thead><tbody>{data.organizations.map((o: Json) => <tr key={o.id} className="border-t border-[#e5e9e5]"><td className="py-3 font-semibold">{o.name}</td>{data.products.map((p: Json) => <td key={p.id}><label className="flex items-center gap-2"><input type="checkbox" checked={on(o.id, p.id)} onChange={e => toggle(o.id, p.id, e.target.checked)} aria-label={`${o.name} ${p.code}`} /></label></td>)}</tr>)}</tbody></table></div>}</div>;
}

function Themes() {
  const [rows, setRows] = useState<Json[]>([]), [error, setError] = useState(""), [notice, setNotice] = useState("");
  const load = () => api("/api/portal?scope=themes").then(r => setRows(r.themes)).catch(x => setError(x.message));
  useEffect(() => { load(); }, []);
  async function create(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); const form = e.currentTarget, f = new FormData(form); try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "create_theme", ...Object.fromEntries(f) }) }); setNotice("Theme created. Link approved publications to it from the moderation desk."); form.reset(); load(); } catch (x) { setError((x as Error).message); } }
  return <div><WorkspaceHead eyebrow="Learning governance" title="Theme authoring" text="Themes group reviewed, relevant publications. A theme is only shown once three distinct organisations contribute to it." />{notice && <div className="mt-6"><Alert text={notice} success /></div>}{error && <div className="mt-6"><Alert text={error} /></div>}
    <div className="mt-7 grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><form onSubmit={create} className="surface p-6"><h2 className="text-lg font-semibold">New theme</h2><div className="mt-5 grid gap-4"><Field label="Title" name="title" value="" /><Field label="Topic" name="topic" value="" /><Field label="Offering" name="offering" value="Financial Analysis Intelligence" /><Field label="Summary" name="summary" area value="" /><Field label="Suggested improvement" name="suggestedImprovement" value="" required={false} /></div><button className="btn-primary mt-6 w-full justify-center" type="submit">Create theme</button></form>
      <section className="space-y-3">{rows.map(t => <article key={t.id} className="surface p-5"><div className="flex justify-between gap-3"><div><span className="text-xs font-bold text-[#7a8780]">{t.id}</span><h3 className="font-bold">{t.title}</h3></div><span className="status">{t.evidenceCount} linked</span></div><p className="mt-2 text-sm text-[#66736d]">{t.summary}</p></article>)}</section></div></div>;
}

function Lab() {
  const [exps, setExps] = useState<Json[]>([]), [teams, setTeams] = useState<Json[]>([]), [error, setError] = useState(""), [notice, setNotice] = useState("");
  const load = () => { api("/api/portal?scope=experiments").then(r => setExps(r.experiments)).catch(x => setError(x.message)); api("/api/portal?scope=teams").then(r => setTeams(r.teams)).catch(() => undefined); };
  useEffect(() => { load(); }, []);
  async function post(form: HTMLFormElement, action: string, msg: string) { const f = new FormData(form); try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action, ...Object.fromEntries(f) }) }); setNotice(msg); form.reset(); load(); } catch (x) { setError((x as Error).message); } }
  async function join(teamId: string) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "join_team", teamId }) }); load(); } catch (x) { setError((x as Error).message); } }
  return <div><WorkspaceHead eyebrow="Employee innovation" title="Experiments & hackathon teams" text="Propose governed experiments and organise hackathon team spaces. Employee-only; never visible to clients." />{notice && <div className="mt-6"><Alert text={notice} success /></div>}{error && <div className="mt-6"><Alert text={error} /></div>}
    <div className="mt-7 grid gap-6 lg:grid-cols-2"><section><form onSubmit={e => { e.preventDefault(); post(e.currentTarget, "submit_experiment", "Experiment submitted."); }} className="surface p-6"><h2 className="text-lg font-semibold">Submit an experiment</h2><div className="mt-4 grid gap-4"><Field label="Title" name="title" value="" /><Field label="Hypothesis" name="hypothesis" area value="" /></div><button className="btn-primary mt-5" type="submit">Submit</button></form><div className="mt-4 space-y-3">{exps.map(x => <article key={x.id} className="surface p-4"><div className="flex justify-between"><b>{x.title}</b><span className="status">{x.status}</span></div><p className="mt-2 text-sm text-[#66736d]">{x.hypothesis}</p></article>)}</div></section>
      <section><form onSubmit={e => { e.preventDefault(); post(e.currentTarget, "create_team", "Team space created."); }} className="surface p-6"><h2 className="text-lg font-semibold">Create a team space</h2><div className="mt-4 grid gap-4"><Field label="Team name" name="name" value="" /><Field label="Brief" name="brief" value="" required={false} /></div><button className="btn-primary mt-5" type="submit">Create team</button></form><div className="mt-4 space-y-3">{teams.map(t => <article key={t.id} className="surface flex items-center justify-between p-4"><div><b>{t.name}</b><div className="text-xs text-[#75827b]">{t.members} member(s) · {t.brief}</div></div>{t.joined ? <span className="status green">Joined</span> : <button onClick={() => join(t.id)} className="btn-secondary">Join</button>}</article>)}</div></section></div></div>;
}

function SupportAccess() {
  const [grants, setGrants] = useState<Json[]>([]), [error, setError] = useState("");
  const load = () => api("/api/portal?scope=support_grants").then(r => setGrants(r.grants)).catch(x => setError(x.message));
  useEffect(() => { load(); }, []);
  async function grant(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "grant_support", email: f.get("email"), hours: Number(f.get("hours")) }) }); load(); } catch (x) { setError((x as Error).message); } }
  async function revoke(id: string) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "revoke_support", id }) }); load(); } catch (x) { setError((x as Error).message); } }
  return <section className="surface mt-6 p-6"><div className="kicker">Support authorisation · audited</div><p className="mt-2 text-sm text-[#66736d]">Time-limited permission for an Azentio moderator to read your non-private records. Private drafts are never exposed.</p>{error && <div className="mt-3"><Alert text={error} /></div>}
    <form onSubmit={grant} className="mt-4 grid gap-3 sm:grid-cols-[1fr_120px_auto]"><Field label="Moderator email" name="email" type="email" value="" /><Field label="Hours" name="hours" type="number" value="4" /><button className="btn-primary self-end" type="submit">Grant</button></form>
    <ul className="mt-4 divide-y divide-[#e5e9e5] text-sm">{grants.map(g => <li key={g.id} className="flex items-center justify-between py-2"><span>{g.id} · {g.status} · until {g.expiresAt}</span>{g.status === "active" && <button onClick={() => revoke(g.id)} className="text-xs font-bold text-[#a34d43]">Revoke</button>}</li>)}</ul></section>;
}

function WorkspaceHead({ eyebrow, title, text, action }: { eyebrow: string; title: string; text: string; action?: React.ReactNode }) { return <div className="flex flex-wrap items-end justify-between gap-5"><div><div className="kicker">{eyebrow}</div><h1 className="mt-2 text-3xl font-semibold tracking-[-.045em] md:text-4xl">{title}</h1><p className="mt-3 max-w-3xl leading-7 text-[#66736d]">{text}</p></div>{action}</div>; }
function SectionHead({ eyebrow, title, text }: { eyebrow: string; title: string; text: string }) { return <div className="max-w-3xl"><div className="kicker">{eyebrow}</div><h2 className="mt-4 text-4xl font-semibold tracking-[-.05em] md:text-6xl">{title}</h2><p className="mt-5 max-w-2xl text-lg leading-8 text-[#617068]">{text}</p></div>; }
function Pill({ children, icon }: { children: React.ReactNode; icon: React.ReactNode }) { return <span className="inline-flex items-center gap-2 rounded-full border border-[#cad8d0] bg-white/70 px-3 py-1.5 text-[11px] font-bold uppercase tracking-[.13em] text-[#3f5e50] shadow-sm">{icon}{children}</span>; }
function Stat({ n, t }: { n: string; t: string }) { return <div><div className="text-2xl font-semibold text-[#bff8e2]">{n}</div><div className="mt-1 text-xs uppercase tracking-[.12em] text-[#a7b8b0]">{t}</div></div>; }
function Step({ n, icon, title, text }: { n: string; icon: React.ReactNode; title: string; text: string }) { return <div className="surface p-6"><div className="flex items-center justify-between"><span className="product-icon mint">{icon}</span><span className="text-xs font-bold text-[#9aa59f]">{n}</span></div><h3 className="mt-8 text-xl font-bold">{title}</h3><p className="mt-3 text-sm leading-6 text-[#68766f]">{text}</p></div>; }
function MiniCard({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="rounded-xl bg-[#f2f5f2] p-3"><span className="text-[#008d70] [&>svg]:h-4 [&>svg]:w-4">{icon}</span><div className="mt-3 text-[10px] text-[#7b8881]">{label}</div><div className="mt-1 text-xs font-bold">{value}</div></div>; }
function Metric({ label, value, icon, note }: { label: string; value: string; icon: React.ReactNode; note: string }) { return <div className="surface flex items-center gap-4 p-5"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-[#e9f4ef] text-[#008d70]">{icon}</span><div><div className="text-2xl font-semibold">{value}</div><div className="text-xs text-[#748179]">{label} · {note}</div></div></div>; }
function Timeline({ label, done }: { label: string; done?: boolean }) { return <div className="flex items-center gap-3"><span className={`grid h-6 w-6 place-items-center rounded-full ${done ? "bg-[#008d70] text-white" : "border border-[#cfd8d1] text-[#a0aaa4]"}`}>{done ? <Check size={13} /> : <Clock3 size={12} />}</span><span className={`text-sm ${done ? "font-semibold" : "text-[#77847d]"}`}>{label}</span></div>; }
function Fact({ k, v }: { k: string; v: string }) { return <div><div className="text-[10px] font-bold uppercase tracking-[.11em] text-[#8a958f]">{k}</div><div className="mt-1 break-words font-semibold text-[#4a5952]">{v}</div></div>; }
function Field({ label, name, type = "text", area, value, required = true }: { label: string; name: string; type?: string; area?: boolean; value?: string; required?: boolean }) { return <label className="field"><span>{label}</span>{area ? <textarea required={required} name={name} defaultValue={value} rows={4} /> : <input required={required} name={name} type={type} defaultValue={value} />}</label>; }
function SelectField({ label, name, options, value, onChange }: { label: string; name: string; options: string[]; value?: string; onChange?: (v: string) => void }) { return <label className="field"><span>{label}</span><select name={name} value={value} onChange={onChange ? e => onChange(e.target.value) : undefined} defaultValue={onChange ? undefined : options[0]}>{options.map(o => <option key={o}>{o}</option>)}</select></label>; }
function Alert({ text, success }: { text: string; success?: boolean }) { return <div className={`flex items-start gap-3 rounded-xl p-4 text-sm ${success ? "bg-[#e9f6f0] text-[#28604e]" : "bg-[#fff0ed] text-[#8f443b]"}`}>{success ? <Check size={16} /> : <CircleAlert size={16} />}<span>{text}</span></div>; }
function Empty({ icon, title, text }: { icon: React.ReactNode; title: string; text: string }) { return <div className="p-8 text-center"><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-[#edf2ee] text-[#708078]">{icon}</span><h3 className="mt-4 font-bold">{title}</h3><p className="mt-2 text-sm leading-6 text-[#75827b]">{text}</p></div>; }
function Success({ result }: { result: Json }) { return <div className="py-8 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-[#daf3e7] text-[#008d70]"><Check /></span><h2 className="mt-5 text-2xl font-semibold">Request recorded</h2><div className="mx-auto mt-4 w-fit rounded-lg bg-[#f0f3f0] px-3 py-2 font-mono text-sm">{result.reference}</div><p className="mt-4 text-sm text-[#68766f]">{result.notification}</p></div>; }
function Loading() { return <main className="grid min-h-[70vh] place-items-center"><div className="text-center"><span className="mx-auto grid h-12 w-12 animate-pulse place-items-center rounded-2xl bg-[#dff2e9] text-[#008d70]"><Network /></span><p className="mt-4 text-sm text-[#718078]">Resolving workspace permissions…</p></div></main>; }
function AccessDenied() { return <div className="surface grid min-h-[430px] place-items-center"><div className="max-w-md p-8 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#fff0ed] text-[#a34d43]"><LockKeyhole /></span><h1 className="mt-5 text-2xl font-semibold">This workspace cannot open that resource</h1><p className="mt-3 text-sm leading-6 text-[#6c7972]">The server-resolved role and audience do not permit this route. Knowing a URL does not grant access.</p><Link href="/login" className="btn-secondary mt-6">Switch authorised workspace</Link></div></div>; }
